    # Condition: For any multiset X of size m from {0, ..., m-1},
    # if sum(X) % m != 0, then there exists a permutation p such that
    # sum j*p_j % m == 0.

    import itertools

    def get_multisets(m):
        def backtrack(current_counts, remaining_m, start_res):
            if remaining_m == 0:
                yield tuple(current_counts)
                return
            for r in range(start_res, m):
                current_counts[r] += 1
                yield from backtrack(current_counts, remaining_m - 1, r)
                current_counts[r] -= 1

        yield from backtrack([0]*m, m, 0)

    # Let's use the prime property and the DP for non-prime m.

    def check_permutation_dp(counts, m):
        memo = {}
        def solve(w_idx, current_sum, current_counts):
            state = (w_idx, current_sum, current_counts)
            if state in memo:
                return memo[state]
            if w_idx > m:
                return current_sum == 0
            for r in range(m):
                if current_counts[r] > 0:
                    new_counts = list(current_counts)
                    new_counts[r] -= 1
                    if solve(w_idx + 1, (current_sum + w_idx * r) % m, tuple(new_counts)):
                        memo[state] = True
                        return True
            memo[state] = False
            return False
        return solve(1, 0, counts)

    # For m = 1 to 10, let's check.
    for m in range(2, 11):
        all_pass = True
