def count_prime_powers(n):
    prime_powers = set()
    for p in range(2, n + 1):
        # Check if p is prime
        is_prime = True
        for i in range(2, int(p**0.5) + 1):
            if p % i == 0:
                is_prime = False
                break
        if is_prime:
            pk = p
            while pk <= n:
                prime_powers.add(pk)
                pk *= p
    return len(prime_powers)

