def check_m_simple_fixed(m):
    s1 = sum(range(m))
    cond1 = (s1 % m == 0)

    found_cond2 = False
    for p in permutations(range(m)):
        s2 = 0
        for i in range(m):
            s2 += (i + 1) * p[i]
        if s2 % m == 0:
            found_cond2 = True
            break
    return cond1, found_cond2

